{
  "claims": [
    {
      "claim_text": "A cache must not use heuristics when an explicit expiration time is present.",
      "verdict": "SUPPORTED",
      "reasoning": "Passage 1 states this directly.",
      "citations": [
        {
          "index": 1,
          "quote": "A cache MUST NOT use heuristics to determine freshness when an explicit expiration time is present in the stored response."
        }
      ]
    },
    {
      "claim_text": "A response with Cache-Control: max-age=600 is never given a heuristic lifetime.",
      "verdict": "SUPPORTED",
      "reasoning": "max-age is an explicit expiration time, and heuristics must not be used when an explicit expiration time is present.",
      "citations": [
        {
          "index": 1,
          "quote": "A cache MUST NOT use heuristics to determine freshness when an explicit expiration time is present in the stored response."
        },
        {
          "index": 0,
          "quote": "The primary mechanism for determining freshness is for an origin server to provide an explicit expiration time in the future, using either the Expires header field (Section 5.3) or the max-age response directive (Section 5.2.2.1)."
        }
      ]
    },
    {
      "claim_text": "If a response has s-maxage=60, a shared cache treats it as fresh for 60 seconds.",
      "verdict": "SUPPORTED",
      "reasoning": "s-maxage specifies the maximum age for a shared cache, overriding max-age and Expires.",
      "citations": [
        {
          "index": 7,
          "quote": "The s-maxage response directive indicates that, for a shared cache, the maximum age specified by this directive overrides the maximum age specified by either the max-age directive or the Expires header field."
        }
      ]
    },
    {
      "claim_text": "A shared cache must ignore any Expires header when s-maxage is present.",
      "verdict": "SUPPORTED",
      "reasoning": "Passage 8 states that a shared cache recipient MUST ignore Expires when s-maxage is present.",
      "citations": [
        {
          "index": 8,
          "quote": "Likewise, if a response includes the s-maxage directive (Section 5.2.2.10), a shared cache recipient MUST ignore the Expires header field."
        }
      ]
    },
    {
      "claim_text": "A client sending max-age=0 without max-stale is asking not to receive a stale response.",
      "verdict": "SUPPORTED",
      "reasoning": "Passage 3 states that unless max-stale is also present, the client does not wish to receive a stale response.",
      "citations": [
        {
          "index": 3,
          "quote": "Unless the max-stale request directive is also present, the client does not wish to receive a stale response."
        }
      ]
    },
    {
      "claim_text": "Since proxy-revalidate applies only to shared caches, a private cache holding a stale response marked proxy-revalidate may reuse it without revalidating.",
      "verdict": "SUPPORTED",
      "reasoning": "Passage 6 says proxy-revalidate does not apply to private caches, so the restriction does not bind a private cache.",
      "citations": [
        {
          "index": 6,
          "quote": "This is analogous to must-revalidate (Section 5.2.2.2), except that proxy-revalidate does not apply to private caches."
        }
      ]
    },
    {
      "claim_text": "must-revalidate binds every cache.",
      "verdict": "SUPPORTED",
      "reasoning": "Passage 5 says in all circumstances a cache MUST NOT ignore must-revalidate.",
      "citations": [
        {
          "index": 5,
          "quote": "In all circumstances, a cache MUST NOT ignore the must-revalidate directive"
        }
      ]
    },
    {
      "claim_text": "A disconnected cache must return an error instead of the stale response when must-revalidate is present.",
      "verdict": "SUPPORTED",
      "reasoning": "Passage 5 states that if a cache is disconnected, it MUST generate an error response rather than reuse the stale response.",
      "citations": [
        {
          "index": 5,
          "quote": "in particular, if a cache is disconnected, the cache MUST generate an error response rather than reuse the stale response."
        }
      ]
    },
    {
      "claim_text": "A client that sends max-stale=30 will accept a response up to 30 seconds past its freshness lifetime.",
      "verdict": "SUPPORTED",
      "reasoning": "Passage 4 states the client is willing to accept a response that has exceeded its freshness lifetime by no more than the specified number of seconds.",
      "citations": [
        {
          "index": 4,
          "quote": "If a value is present, then the client is willing to accept a response that has exceeded its freshness lifetime by no more than the specified number of seconds."
        }
      ]
    },
    {
      "claim_text": "A client that sends max-stale=30 will not accept a response that is 45 seconds stale.",
      "verdict": "SUPPORTED",
      "reasoning": "45 seconds exceeds the specified 30 seconds, so the client is not willing to accept it under max-stale=30.",
      "citations": [
        {
          "index": 4,
          "quote": "If a value is present, then the client is willing to accept a response that has exceeded its freshness lifetime by no more than the specified number of seconds."
        }
      ]
    },
    {
      "claim_text": "If two suitable responses are stored, a cache uses the one with the earlier Date header.",
      "verdict": "CONTRADICTED",
      "reasoning": "Passage 9 says the cache MUST use the most recent one as determined by the Date header, not the earlier one.",
      "citations": [
        {
          "index": 9,
          "quote": "When more than one suitable response is stored, a cache MUST use the most recent one (as determined by the Date header field)."
        }
      ]
    }
  ]
}
